#!/usr/bin/env python3
"""Patch an ares settings.bml (generated by a first run) into the headless template."""
import sys
src, dst = sys.argv[1], sys.argv[2]
KB = "0x1/0/{}"   # Xlib keyboard device id 0x1, group 0 (Button), input index
IDX = {"Escape":0,"F1":1,"F2":2,"F3":3,"F4":4,"F5":5,"F6":6,"F7":7,"F8":8,"F9":9,"F10":10,"F11":11,"F12":12,
       "A":35,"C":37,"D":38,"E":39,"I":43,"J":44,"K":45,"L":46,"Q":51,"S":53,"W":57,"X":58,"Z":60,
       "Up":84,"Down":85,"Left":86,"Right":87,"Return":89,"Space":90}
def k(name): return KB.format(IDX[name]) + ";;"
overrides = {
  "Video/Driver": "OpenGL 3.2",
  "Video/Blocking": "false",
  "Video/WindowWidth": "640", "Video/WindowHeight": "480",
  "Video/Output": "Scale", "Video/FixedScale": "2",
  "Audio/Blocking": "false", "Audio/Mute": "true",
  "Input/Defocus": "Allow",
  "General/ShowStatusBar": "false",
  "General/NoFilePrompt": "true",
  "General/AutoSaveMemory": "false",
  "Developer/HomebrewMode": "true",
  # VirtualPad1 <- keyboard (N64 core maps Gamepad -> VirtualPad1 by default)
  "VirtualPad1/Pad.Up": k("I"), "VirtualPad1/Pad.Down": k("K"),
  "VirtualPad1/Pad.Left": k("J"), "VirtualPad1/Pad.Right": k("L"),
  "VirtualPad1/Start": k("Return"),
  "VirtualPad1/A..South": k("X"),      # N64 A
  "VirtualPad1/X..West": k("C"),       # N64 B
  "VirtualPad1/L-Bumper": k("Q"),      # N64 L
  "VirtualPad1/R-Bumper": k("E"),      # N64 R
  "VirtualPad1/R-Trigger": k("Z"),     # N64 Z
  "VirtualPad1/L-Up": k("Up"), "VirtualPad1/L-Down": k("Down"),
  "VirtualPad1/L-Left": k("Left"), "VirtualPad1/L-Right": k("Right"),
  "VirtualPad1/R-Up": k("W"), "VirtualPad1/R-Down": k("S"),       # C-Up / C-Down
  "VirtualPad1/R-Left": k("A"), "VirtualPad1/R-Right": k("D"),    # C-Left / C-Right
  "Hotkey/CaptureScreenshot": k("F12"),
  "Hotkey/PauseEmulation": k("F9"),
}
out, stack, seen = [], [], set()
for line in open(src).read().split("\n"):
    if not line.strip(): out.append(line); continue
    depth = (len(line) - len(line.lstrip(" "))) // 2
    name = line.strip().split(":", 1)[0]
    stack[depth:] = [name]
    path = "/".join(stack)
    if path in overrides:
        line = "  " * depth + name + ": " + overrides[path]; seen.add(path)
    out.append(line)
missing = set(overrides) - seen
if missing: sys.exit("missing settings paths: %s" % sorted(missing))
open(dst, "w").write("\n".join(out))
